export const paper = { year: 2023, name: 'GS1', set: 'A' };

export const questions = [
{"no":1,"text":"Consider the following statements:\nJhelum River passes through Wular Lake.\nKrishna River directly feeds Kolleru Lake.\nMeandering of Gandak River formed Kanwar Lake.\nHow many of the statements given above are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"A","category":"Geography","subcategory":"Physical Geography","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nThe Jhelum River passes through Wular Lake in Jammu and Kashmir.\nWular is a major freshwater lake of the Kashmir Valley.\nStatement 2 — Incorrect\nKolleru Lake is located in Andhra Pradesh.\nIt lies between the Krishna and Godavari deltaic regions.\nKrishna does not directly feed Kolleru Lake.\nStatement 3 — Incorrect\nKanwar Lake, also known as Kabar Taal, is associated with the Burhi Gandak River.","revisionPoints":"Jhelum → Wular Lake\nBurhi Gandak → Kanwar/Kabar Taal\nKolleru Lake → Andhra Pradesh\nRiver meandering can result in:\nCut-off meander\nOxbow lake\nWetland\nUPSC Trap: Gandak ≠ Burhi Gandak."},
{"no":2,"text":"Consider the following pairs:\nPort\nWell known as\n1. Kamarajar Port\nFirst major port in India registered as a company\n2. Mundra Port\nLargest privately owned port in India\n3. Visakhapatnam Port\nLargest container port in India\nHow many of the above pairs are correctly matched?","A":"Only one pair","B":"Only two pairs","C":"All three pairs","D":"None of the pairs","ans":"A","category":"Economy","subcategory":"Infrastructure & Transport","tags":["UPSC","2023"],"expl":"Pair 1 — Correct\nKamarajar Port, formerly known as Ennore Port, is notable for being the first major port in India registered as a company.\nIt is located in Tamil Nadu.\nPair 2 — Incorrect\nMundra Port is a major private port in Gujarat.\nThe description given is not the intended correct identification in the question.\nPair 3 — Incorrect\nVisakhapatnam Port is an important major port on India's eastern coast.\nIt is not India's largest container port.","revisionPoints":"Kamarajar Port → Tamil Nadu\nMundra Port → Gujarat\nVisakhapatnam Port → Andhra Pradesh\nParadip Port → Odisha\nDeendayal Port → Gujarat\nKochi Port → Kerala\nMumbai Port → Maharashtra\nChennai Port → Tamil Nadu\nUPSC Trap\nPay attention to words such as:\nFirst\nLargest\nOldest\nOnly\nHighest\nThese are frequently used to create close options."},
{"no":3,"text":"Consider the following trees:\nJackfruit (Artocarpus heterophyllus)\nMahua (Madhuca indica)\nTeak (Tectona grandis)\nHow many of the above are deciduous trees?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"C","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"Jackfruit — Correct\nTreated as deciduous in the classification used in the question.\nMahua — Correct\nMahua is an important deciduous tree.\nIt is particularly associated with central and eastern Indian forests.\nTeak — Correct\nTeak is a classic species of tropical deciduous forests.\nTherefore, all three are counted as deciduous.","revisionPoints":"Teak → Tropical deciduous forests\nSal → Tropical deciduous forests\nMahua → Deciduous tree\nTropical deciduous forests generally occur in areas having a distinct dry season.\nTropical ≠ automatically evergreen\nUPSC Trap\nDo not assume that every tropical forest is an evergreen forest."},
{"no":4,"text":"Consider the following statements:\nIndia has more arable area than China.\nThe proportion of irrigated area is more in India as compared to China.\nThe average productivity per hectare in Indian agriculture is higher than that in China.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"A","category":"Geography","subcategory":"Economic Geography","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nIndia has a very large agricultural area.\nIn the comparison intended by the question, India has a larger arable land base than China.\nStatement 2 — Incorrect\nThe proportion of irrigated agricultural area is not higher in India than China in the manner stated.\nStatement 3 — Incorrect\nIndia's average agricultural productivity per hectare is generally lower than China's for many important crops.","revisionPoints":"When comparing agricultural systems, revise:\nArable land\nIrrigated area\nYield per hectare\nCropping intensity\nFarm mechanisation\nFertiliser use\nWater availability\nAgricultural labour\nUPSC Trap\nLarge agricultural area ≠ high agricultural productivity"},
{"no":5,"text":"Which one of the following is the best example of repeated falls in sea level, giving rise to present-day extensive marshland?","A":"Bhitarkanika Mangroves","B":"Marakkanam Salt Pans","C":"Naupada Swamp","D":"Rann of Kutch","ans":"D","category":"Geography","subcategory":"Physical Geography","tags":["UPSC","2023"],"expl":"The Rann of Kutch is an extensive seasonal saline marshland in Gujarat.\nIts geographical character has been influenced by:\nChanges in sea level\nGeological processes\nTectonic activity\nDuring the dry season, large areas become exposed as salt-covered marshes.\nDuring the monsoon, parts become inundated.","revisionPoints":"Rann of Kutch → Gujarat\nGreat Rann + Little Rann\nExtensive saline marsh\nSeasonal inundation\nSalt-rich environment\nImportant wetland ecosystem\nLittle Rann → Indian Wild Ass\nRann → Saline marsh\nMangrove → Salt-tolerant coastal vegetation\nSalt pan → Salt production\nSwamp → Waterlogged land"},
{"no":6,"text":"Ilmenite and rutile, abundantly available in certain coastal tracts of India, are rich sources of which one of the following?","A":"Aluminium","B":"Copper","C":"Iron","D":"Titanium","ans":"D","category":"Economy","subcategory":"Mining & Minerals","tags":["UPSC","2023"],"expl":"Ilmenite and rutile are important titanium-bearing minerals.\nThey are found in heavy mineral sands along certain coastal regions of India.\nTitanium is used in:\nAerospace\nDefence\nPigments\nChemical industries\nHigh-strength alloys","revisionPoints":"Mineral\nMajor resource\nIlmenite\nTitanium\nRutile\nTitanium\nBauxite\nAluminium\nHematite\nIron\nMagnetite\nIron\nChalcopyrite\nCopper\nUPSC Trap\nIlmenite + Rutile → Titanium"},
{"no":7,"text":"About three-fourths of the world's cobalt, a metal required for the manufacture of batteries for electric motor vehicles, is produced by:","A":"Argentina","B":"Botswana","C":"Democratic Republic of the Congo","D":"Kazakhstan","ans":"C","category":"Economy","subcategory":"Mining & Minerals","tags":["UPSC","2023"],"expl":"The Democratic Republic of the Congo (DRC) is the dominant source of mined cobalt.\nCobalt is important for:\nBattery technologies\nElectric vehicles\nAerospace applications\nSuperalloys\nChemical industries","revisionPoints":"DRC → Cobalt\nCobalt → Rechargeable batteries\nCobalt → Electric vehicles\nCobalt → Aerospace applications\nCobalt → Superalloys\nCobalt → Chemical industries\nCritical mineral:\nGeographical concentration\nSupply-chain vulnerability\nStrategic importance\nUPSC Trap\nFor critical minerals, remember the country + mineral combination."},
{"no":8,"text":"Which one of the following is a part of the Congo Basin?","A":"Cameroon","B":"Nigeria","C":"South Sudan","D":"Uganda","ans":"A","category":"Geography","subcategory":"Physical Geography","tags":["UPSC","2023"],"expl":"The Congo Basin is a major drainage basin and rainforest region in Central Africa.\nIt extends across several countries, including Cameroon.\nThe Congo rainforest is one of the world's major tropical rainforest ecosystems.","revisionPoints":"Countries associated with the Congo Basin include:\nDemocratic Republic of Congo\nRepublic of Congo\nCameroon\nGabon\nCentral African Republic\nEquatorial Guinea\nUPSC Trap\nThe Congo Basin is not limited to the Democratic Republic of Congo."},
{"no":9,"text":"Consider the following statements:\nAmarkantak Hills are at the confluence of Vindhya and Sahyadri Ranges.\nBiligirirangan Hills constitute the easternmost part of Satpura Range.\nSeshachalam Hills constitute the southernmost part of Western Ghats.\nHow many of the statements given above are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"A","category":"Geography","subcategory":"Physical Geography","tags":["UPSC","2023"],"expl":"Statement 1 — Correct in the geographical sense intended by the question\nAmarkantak is an important highland and watershed region.\nIt is associated with major central Indian hill systems.\nIt is particularly important as the source region of the Narmada and Son rivers.\nStatement 2 — Incorrect\nBiligirirangan Hills are in southern Karnataka.\nThey form an ecological link between the Western Ghats and Eastern Ghats.\nThey are not the easternmost part of the Satpura Range.\nStatement 3 — Incorrect\nSeshachalam Hills are in Andhra Pradesh.\nThey belong to the Eastern Ghats.\nThey are not the southernmost part of the Western Ghats.","revisionPoints":"Amarkantak → Narmada + Son source region\nBiligirirangan → Karnataka\nBiligirirangan → Western/Eastern Ghats connection\nSeshachalam → Andhra Pradesh\nSeshachalam → Eastern Ghats\nWestern Ghats → Western side of Peninsular India\nEastern Ghats → Eastern side and discontinuous\nUPSC Trap\nUPSC can change the mountain system while keeping the location approximately plausible."},
{"no":10,"text":"With reference to India's projects on connectivity, consider the following statements:\nEast-West Corridor under Golden Quadrilateral Project connects Dibrugarh and Porbandar.\nTrilateral Highway connects Moreh in Manipur and Chiang Mai in Thailand via Myanmar.\nBangladesh-China-India-Myanmar Economic Corridor connects Varanasi with Kunming.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"D","category":"International Relations","subcategory":"Connectivity Projects","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nEast-West Corridor broadly connects Silchar and Porbandar.\nIt does not connect Dibrugarh with Porbandar.\nStatement 2 — Incorrect\nIndia–Myanmar–Thailand Trilateral Highway connects Moreh in Manipur through Myanmar towards Mae Sot in Thailand.\nIt does not terminate at Chiang Mai.\nStatement 3 — Incorrect\nBCIM Economic Corridor has been associated with connectivity between Kolkata and Kunming.\nNot Varanasi and Kunming.","revisionPoints":"Project\nRoute\nEast-West Corridor\nSilchar ↔ Porbandar\nIndia–Myanmar–Thailand Trilateral Highway\nMoreh ↔ Mae Sot\nBCIM Economic Corridor\nKolkata ↔ Kunming\nUPSC Trap\nFor connectivity questions remember:\nProject → Starting point → Route → Ending point → Countries"},
{"no":11,"text":"Consider the following statements:\nStatement-I: India, despite having uranium deposits, depends on coal for most of its electricity production.\nStatement-II: Uranium, enriched to the extent of at least 60%, is required for the production of electricity.\nWhich one of the following is correct?","A":"Both Statement-I and Statement-II are correct and Statement-II explains Statement-I.","B":"Both Statement-I and Statement-II are correct, but Statement-II does not explain Statement-I.","C":"Statement-I is correct, but Statement-II is incorrect.","D":"Statement-I is incorrect, but Statement-II is correct.","ans":"C","category":"Science & Technology","subcategory":"Nuclear Technology","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nIndia has uranium resources.\nHowever, coal has historically been the dominant source of electricity generation.\nIndia's nuclear power capacity is much smaller than its coal-based power capacity.\nStatement-II — Incorrect\nNuclear electricity generation does not generally require uranium enriched to at least 60%.\nMany reactors use low-enriched uranium.\nSome reactor designs can use natural uranium.","revisionPoints":"Coal → Major source of India's electricity\nUranium → Nuclear fuel\nUranium enrichment → Increasing proportion of U-235\nRequired enrichment depends on:\nReactor design\nFuel cycle\nCivilian nuclear fuel generally uses much lower enrichment than highly enriched uranium.\nUPSC Trap\nNuclear reactor ≠ necessarily highly enriched uranium"},
{"no":12,"text":"Consider the following statements:\nStatement-I: Marsupials are not naturally found in India.\nStatement-II: Marsupials can thrive only in montane grasslands with no predators.\nWhich one of the following is correct?","A":"Both Statement-I and Statement-II are correct and Statement-II explains Statement-I.","B":"Both Statement-I and Statement-II are correct, but Statement-II does not explain Statement-I.","C":"Statement-I is correct, but Statement-II is incorrect.","D":"Statement-I is incorrect, but Statement-II is correct.","ans":"C","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nLiving marsupials are mainly associated with:\nAustralia\nNew Guinea\nThe Americas\nThey are not naturally distributed in India.\nExamples:\nKangaroo\nKoala\nWombat\nWallaby\nOpossum\nTasmanian devil\nStatement-II — Incorrect\nMarsupials do not require montane grasslands.\nThey occupy diverse habitats:\nForests\nGrasslands\nWoodlands\nDeserts\nWetlands","revisionPoints":"Marsupial → Distinctive reproductive strategy\nYoung are born relatively underdeveloped.\nFurther development occurs associated with the mother's pouch/teat.\nAustralia → Rich marsupial diversity\nExamples:\nKangaroo\nKoala\nWombat\nWallaby\nOpossum\nUPSC Trap\nBe careful with absolute words such as “only” in habitat statements."},
{"no":13,"text":"Invasive Species Specialist Group that develops Global Invasive Species Database belongs to which one of the following organizations?","A":"International Union for Conservation of Nature (IUCN)","B":"United Nations Environment Programme (UNEP)","C":"United Nations World Commission for Environment and Development","D":"World Wide Fund for Nature (WWF)","ans":"A","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"The Invasive Species Specialist Group (ISSG) is associated with the IUCN.\nIt developed the Global Invasive Species Database (GISD).\nInvasive alien species:\nAre introduced outside their natural geographical range.\nCan become established.\nCan cause ecological, economic or social harm.","revisionPoints":"IUCN → International Union for Conservation of Nature\nIUCN Red List\nSpecies conservation assessments\nInvasive Species Specialist Group\nConservation status of species\nUPSC Trap\nIUCN → Conservation assessment / Red List\nUNEP → UN environmental programme\nWWF → International conservation organisation"},
{"no":14,"text":"Consider the following fauna:\nLion-tailed Macaque\nMalabar Civet\nSambar Deer\nHow many of the above are generally nocturnal or most active after sunset?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"B","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"Lion-tailed Macaque — Not nocturnal\nPrimarily diurnal.\nMainly active during daytime.\nArboreal primate of evergreen forests of the Western Ghats.\nMalabar Civet — Nocturnal\nPrimarily active during the night.\nSambar Deer — Generally active around dusk/night\nCan be active at different times.\nCommonly shows increased activity during crepuscular and nocturnal periods.\nTherefore:\nLion-tailed Macaque → ❌\nMalabar Civet → ✅\nSambar → ✅","revisionPoints":"Lion-tailed macaque → Mainly diurnal\nMalabar civet → Nocturnal\nSambar → Often crepuscular/nocturnal\nDiurnal → Daytime\nNocturnal → Nighttime\nCrepuscular → Dawn and dusk\nUPSC Trap\n“Can be active at night” ≠ “generally nocturnal.”"},
{"no":15,"text":"Which one of the following organisms perform waggle dance for others of their kin to indicate the direction and the distance to a source of their food?","A":"Butterflies","B":"Dragonflies","C":"Honeybees","D":"Wasps","ans":"C","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"The waggle dance is a communication behaviour of honeybees.\nA foraging bee returning to the colony communicates information about a food source.\nThe dance provides information about:\nDirection\nDistance\nThis helps other bees locate the food source.","revisionPoints":"Honeybee → Waggle dance\nWaggle dance communicates:\nFood-source direction\nFood-source distance\nRelated concepts:\nAnimal communication\nSocial behaviour\nBehavioural ecology\nCollective decision-making\nUPSC Trap\nWaggle dance is related to food-source communication, not mating or territorial behaviour."},
{"no":16,"text":"Consider the following statements:\nSome mushrooms have medicinal properties.\nSome mushrooms have psychoactive properties.\nSome mushrooms have insecticidal properties.\nSome mushrooms have bioluminescent properties.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"D","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nSome mushrooms contain compounds with medicinal significance.\nStatement 2 — Correct\nCertain mushrooms contain psychoactive compounds such as psilocybin.\nStatement 3 — Correct\nCertain fungi produce compounds that can affect insects.\nThese can have applications in biological control.\nStatement 4 — Correct\nSome fungi are bioluminescent.\nThey produce visible light through biochemical reactions.","revisionPoints":"Fungi have roles in:\nFood\nMedicine\nDecomposition\nFermentation\nBiological control\nToxins\nBioluminescence\nImportant Concept\nA mushroom is the fruiting structure of certain fungi.\nIt is not a separate biological kingdom."},
{"no":17,"text":"Consider the following statements:\nThey build nests by making burrows in the ground.\nThey store their food materials like nuts and seeds in the ground.\nThey are omnivorous.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"B","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nMany Indian squirrels are arboreal/tree-dwelling.\nThey generally construct nests in trees rather than underground burrows.\nStatement 2 — Correct\nSquirrels can store/cache food.\nExamples include:\nNuts\nSeeds\nStatement 3 — Correct\nSquirrels are generally omnivorous.\nTheir diet may include:\nSeeds\nNuts\nFruits\nPlant material\nInsects\nOther animal matter\nTherefore, Statements 2 and 3 are correct.","revisionPoints":"Many squirrels → Arboreal\nBuild nests → Trees\nCache/store food\nGenerally omnivorous\nEcology approach:\nAnimal → Habitat → Behaviour\nUPSC Trap\nThe word “burrows” may create a false association with terrestrial mammals."},
{"no":18,"text":"Consider the following statements:\nSome microorganisms can grow in environments with temperature above the boiling point of water.\nSome microorganisms can grow in environments with temperature below the freezing point of water.\nSome microorganisms can grow in highly acidic environment with a pH below 3.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"C","category":"Science & Technology","subcategory":"Biology","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nSome hyperthermophiles can grow at temperatures above 100°C under suitable conditions.\nHigh pressure can allow water to remain liquid above its normal boiling point.\nStatement 2 — Correct\nPsychrophiles are microorganisms adapted to very low temperatures.\nThey can grow below the freezing point under suitable conditions.\nStatement 3 — Correct\nAcidophiles can survive and grow in highly acidic environments.\nSome can grow at pH values below 3.","revisionPoints":"Organism\nExtreme condition\nThermophile\nHigh temperature\nHyperthermophile\nExtremely high temperature\nPsychrophile\nVery low temperature\nAcidophile\nHigh acidity\nHalophile\nHigh salinity\nPiezophile\nHigh pressure\nUPSC Trap\nThe boiling point of water is pressure-dependent."},
{"no":19,"text":"Which one of the following makes a tool with a stick to scrape insects from a hole in a tree or a log of wood?","A":"Fishing cat","B":"Orangutan","C":"Otter","D":"Sloth bear","ans":"B","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"Orangutans demonstrate sophisticated tool-use behaviour.\nThey can use sticks to obtain food from difficult-to-reach locations.\nThis includes extracting insects from holes.\nThis demonstrates:\nProblem-solving\nTool use\nCognitive ability\nBehavioural adaptation","revisionPoints":"Orangutans → Stick tools\nSome primates → Tools for obtaining food\nSome birds → Tools for extracting prey\nOtters → Use stones to open certain prey\nAnimal tool use → Behavioural ecology + Animal cognition\nUPSC Trap\nThe question tests a specific behavioural characteristic, not simply the animal's diet."},
{"no":20,"text":"Consider the following:\nAerosols\nFoam agents\nFire retardants\nLubricants\nIn the making of how many of the above are hydrofluorocarbons (HFCs) used?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"D","category":"Environment & Ecology","subcategory":"Pollution","tags":["UPSC","2023"],"expl":"HFCs have been used in several industrial applications.\nTheir applications have included:\nAerosol propellants\nFoaming agents\nCertain fire-protection/fire-suppression applications\nVarious specialised industrial applications\nHowever, many HFCs have high global-warming potential.","revisionPoints":"CFCs:\nOzone depletion\nGreenhouse gases\nHFCs:\nGenerally do not deplete stratospheric ozone\nMany have significant/high global-warming potential\nMontreal Protocol:\nOriginally focused on controlling ozone-depleting substances.\nKigali Amendment:\nPhasedown of HFCs.\nUPSC Trap\nRemember the distinction:\nCFC → Ozone depletion problem\nHFC → Global warming/climate impact"},
{"no":21,"text":"Consider the following statements:\nStatement-I: Interest income from the deposits in Infrastructure Investment Trusts (InvITs) distributed to their investors is exempted from tax, but the dividend is taxable.\nStatement-II: InvITs are recognized as borrowers under the Securitization and Reconstruction of Financial Assets and Enforcement of Security Interest Act, 2002.\nWhich one of the following is correct?","A":"Both Statement-I and Statement-II are correct and Statement-II explains Statement-I.","B":"Both Statement-I and Statement-II are correct, but Statement-II does not explain Statement-I.","C":"Statement-I is correct, but Statement-II is incorrect.","D":"Statement-I is incorrect, but Statement-II is correct.","ans":"D","category":"Economy","subcategory":"Financial Markets","tags":["UPSC","2023"],"expl":"Statement-I — Incorrect\nThe tax treatment of InvIT distributions cannot be stated simply as:\nInterest → Exempt\nDividend → Taxable\nTax treatment depends on:\nNature of income\nSource of distribution\nApplicable tax provisions\nStatement-II — Correct\nInvITs are recognised as borrowers under the SARFAESI Act, 2002, subject to relevant provisions.","revisionPoints":"InvIT → Infrastructure Investment Trust\nUsed as an investment vehicle for infrastructure assets.\nImportant concepts:\nInfrastructure financing\nCapital markets\nAsset monetisation\nInvestment trusts\nTaxation\nTax treatment depends on the nature and source of distribution."},
{"no":22,"text":"Consider the following statements:\nStatement-I: In the post-pandemic recent past, many Central Banks worldwide had carried out interest rate hikes.\nStatement-II: Central Banks generally assume that they have the ability to counteract the rising consumer prices via monetary policy.\nWhich one of the following is correct?","A":"Both Statement-I and Statement-II are correct and Statement-II explains Statement-I.","B":"Both Statement-I and Statement-II are correct, but Statement-II does not explain Statement-I.","C":"Statement-I is correct, but Statement-II is incorrect.","D":"Statement-I is incorrect, but Statement-II is correct.","ans":"A","category":"Economy","subcategory":"Banking & Monetary Policy","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nAfter the pandemic, many countries experienced strong inflationary pressures.\nCentral banks responded by increasing policy interest rates.\nStatement-II — Correct\nMonetary policy can influence:\nBorrowing costs\nConsumption\nInvestment\nAggregate demand\nInflationary pressure\nBasic transmission:\nPolicy rate ↑\n→ Borrowing cost ↑\n→ Consumption/Investment ↓\n→ Aggregate demand pressure ↓\n→ Inflationary pressure may decline\nTherefore, Statement-II explains Statement-I.","revisionPoints":"Monetary Policy\nInterest rates\nLiquidity\nCredit\nInflation\nMonetary conditions\nFiscal Policy\nTaxation\nGovernment expenditure\nGovernment borrowing\nPublic investment\nMonetary policy can influence demand-side inflation.\nSupply shocks such as crop failure or international commodity disruptions cannot be directly eliminated through monetary policy."},
{"no":23,"text":"Consider the following statements:\nStatement-I: Carbon markets are likely to be one of the most widespread tools in the fight against climate change.\nStatement-II: Carbon markets transfer resources from the private sector to the State.\nWhich one of the following is correct?","A":"Both Statement-I and Statement-II are correct and Statement-II explains Statement-I.","B":"Both Statement-I and Statement-II are correct, but Statement-II does not explain Statement-I.","C":"Statement-I is correct but Statement-II is incorrect.","D":"Statement-I is incorrect but Statement-II is correct.","ans":"B","category":"Environment & Ecology","subcategory":"Climate Change","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nCarbon markets give greenhouse-gas emissions an economic value.\nThey can encourage:\nEmission reduction\nEnergy efficiency\nCleaner technologies\nTrading of emission allowances or credits\nStatement-II — Correct in the context of the question\nCarbon-market mechanisms can involve financial transfers from private entities to governments.\nThis can occur through:\nCarbon pricing\nGovernment-created allowance systems\nHowever, this transfer of resources is not the fundamental reason carbon markets are useful.","revisionPoints":"Carbon Tax\nGovernment sets a price on emissions.\nCap-and-Trade\nGovernment sets an emissions cap.\nEmission allowances can be traded.\nCore purpose of carbon markets:\nCreate economic incentives.\nEncourage reduction in greenhouse-gas emissions.\nPromote cleaner technologies."},
{"no":24,"text":"Which one of the following activities of the Reserve Bank of India is considered to be part of 'sterilization'?","A":"Conducting Open Market Operations","B":"Oversight of settlement and payment systems","C":"Debt and cash management for the Central and State Governments","D":"Regulating the functions of Non-Banking Financial Institutions","ans":"A","category":"Economy","subcategory":"Banking & Monetary Policy","tags":["UPSC","2023"],"expl":"Sterilization refers to actions taken by a central bank to neutralise the effect of foreign-exchange intervention on domestic liquidity.\nExample:\nRBI buys foreign currency.\nRBI pays for it with rupees.\nDomestic rupee liquidity increases.\nIf RBI wants to absorb the additional liquidity:\nRBI sells government securities.\nRupee liquidity is absorbed.\nSuch operations can form part of sterilization.","revisionPoints":"Open Market Operations\nRBI buys government securities → Liquidity increases\nRBI sells government securities → Liquidity decreases\nSterilization\nNeutralises the liquidity/monetary effect of foreign-exchange intervention.\nKey concept:\nForex intervention → Liquidity impact → Central bank neutralises it"},
{"no":25,"text":"Consider the following markets:\nGovernment Bond Market\nCall Money Market\nTreasury Bill Market\nStock Market\nHow many of the above are included in capital markets?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"B","category":"Economy","subcategory":"Financial Markets","tags":["UPSC","2023"],"expl":"Government Bond Market — Capital Market\nGovernment bonds generally represent longer-term borrowing.\nCall Money Market — Money Market\nDeals with very short-term funds, particularly overnight borrowing and lending.\nTreasury Bill Market — Money Market\nTreasury bills are short-term government securities.\nStock Market — Capital Market\nShares and equities form part of the capital market.\nTherefore:\nGovernment Bond Market → Capital Market\nStock Market → Capital Market\nTotal = 2","revisionPoints":"Money Market\nCapital Market\nShort-term\nMedium/long-term\nCall money\nShares\nTreasury bills\nLong-term bonds\nCommercial paper\nDebentures\nCertificates of deposit\nEquity securities\nMoney Market → Short-term funds\nCapital Market → Medium/long-term funds"},
{"no":26,"text":"Which one of the following best describes the concept of 'Small Farmer Large Field'?","A":"Resettlement of displaced people by giving them a large cultivable land.","B":"Many marginal farmers organize themselves into groups and synchronize agricultural operations.","C":"Farmers surrender land to a corporate body for fixed payment.","D":"Company provides loans and technical knowledge to farmers for contract farming.","ans":"B","category":"Economy","subcategory":"Agriculture & Allied","tags":["UPSC","2023"],"expl":"The Small Farmer Large Field approach allows small and marginal farmers to:\nRetain individual land ownership.\nCoordinate agricultural operations.\nFarmers can synchronise:\nSowing\nIrrigation\nCrop management\nHarvesting\nMachinery use\nThe objective is to obtain advantages of large-scale coordinated farming without transferring ownership of land.","revisionPoints":"Small individual holdings + Collective/Synchronised operations\nPotential benefits:\nMechanisation\nInput efficiency\nBetter farm management\nGreater bargaining power\nEfficient use of machinery\nCoordinated agricultural operations"},
{"no":27,"text":"Consider the following statements:\nThe Government of India provides Minimum Support Price (MSP) for niger (Guizotia abyssinica) seeds.\nNiger is cultivated as a Kharif crop.\nSome tribal people in India use niger seed oil for cooking.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"C","category":"Economy","subcategory":"Agriculture & Allied","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nNiger seed is among the agricultural commodities for which the government announces MSP.\nStatement 2 — Correct\nNiger is generally grown as a Kharif oilseed crop.\nIt is particularly associated with rainfed areas.\nStatement 3 — Correct\nNiger seed oil is traditionally used as a cooking oil by some tribal and rural communities.","revisionPoints":"Niger → Guizotia abyssinica\nNiger → Oilseed\nMainly → Kharif crop\nSuitable for → Rainfed conditions\nImportant in → Tribal/rural regions\nCovered under → MSP"},
{"no":28,"text":"Consider the following investments in the following assets:\nBrand recognition\nInventory\nIntellectual property\nMailing list of clients\nHow many of the above are considered intangible investments?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"C","category":"Economy","subcategory":"Basic Concepts","tags":["UPSC","2023"],"expl":"1. Brand recognition — Intangible\nBrand value and recognition can generate economic benefits.\n2. Inventory — Not intangible\nInventory consists of physical goods or materials.\n3. Intellectual property — Intangible\nExamples:\nPatents\nCopyrights\nTrademarks\n4. Mailing list of clients — Intangible\nA commercially valuable customer database/list can possess economic value.\nTherefore:\nBrand recognition → ✅\nInventory → ❌\nIntellectual property → ✅\nMailing list → ✅\nTotal = 3","revisionPoints":"Examples of intangible assets:\nIntellectual property\nSoftware\nBrand value\nCustomer relationships\nDatabases\nProprietary knowledge\nBasic distinction:\nTangible → Physical form\nIntangible → No physical form but economic value"},
{"no":29,"text":"Consider the following:\nDemographic performance\nForest and ecology\nGovernance reforms\nStable government\nTax and fiscal efforts\nFor the horizontal tax devolution, the Fifteenth Finance Commission used how many of the above as criteria other than population, area and income distance?","A":"Only two","B":"Only three","C":"Only four","D":"All five","ans":"A","category":"Economy","subcategory":"Public Finance","tags":["UPSC","2023"],"expl":"1. Demographic performance — Correct\nIt was included as a criterion.\n2. Forest and ecology — Correct\nIncluded to recognise ecological contributions and forest cover.\n3. Governance reforms — Incorrect\nNot one of the criteria listed for horizontal tax devolution.\n4. Stable government — Incorrect\nNot a devolution criterion.\n5. Tax and fiscal efforts\nThe source notes this as part of the broader Finance Commission framework.\nHowever, it was not counted in the manner specified by this question.\nTherefore, according to the supplied source, the intended answer is two.","revisionPoints":"Horizontal Devolution\nDistribution of the divisible pool of central taxes among States.\nImportant criteria include:\nPopulation\nArea\nIncome distance\nForest and ecology\nDemographic performance\nTax and fiscal efforts\nVertical Devolution\nCentre ↔ States\nHorizontal Devolution\nState ↔ State"},
{"no":30,"text":"Consider the following infrastructure sectors:\nAffordable housing\nMass rapid transport\nHealth care\nRenewable energy\nOn how many of the above does UNOPS Sustainable Investments in Infrastructure and Innovation (S3i) initiative focus?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"D","category":"Economy","subcategory":"Infrastructure & Transport","tags":["UPSC","2023"],"expl":"The Sustainable Investments in Infrastructure and Innovation (S3i) initiative of UNOPS focuses on sustainable infrastructure investment.\nAreas include:\nAffordable housing\nMass rapid transport\nHealthcare\nRenewable energy\nTherefore, all four are covered.","revisionPoints":"UNOPS → United Nations Office for Project Services\nMajor areas of work:\nInfrastructure\nProcurement\nProject management\nSustainable development\nImplementation support\nS3i → Sustainable Infrastructure + Investment + Innovation"},
{"no":31,"text":"In essence, what does ‘Due Process of Law’ mean?","A":"The principle of natural justice","B":"The procedure established by law","C":"Fair application of law","D":"Equality before law","ans":"A","category":"Polity & Governance","subcategory":"Constitution","tags":["UPSC","2023"],"expl":"Due Process of Law is based on the idea of fairness and justice in legal proceedings.\nIt requires that a person should not be deprived of life or liberty through an arbitrary or unfair process.\nIt is closely connected with the principles of natural justice.\nNatural justice includes:\nRight to a fair hearing\nAbsence of bias\nFair and reasonable decision-making\nProcedure established by law is a narrower concept.\nIn India, the interpretation of Article 21 was expanded through the Maneka Gandhi v. Union of India judgment to incorporate requirements of fairness and reasonableness.","revisionPoints":"Due Process of Law → Natural justice + fairness\nProcedure established by law → Article 21\nNatural justice:\nAudi alteram partem → Hear the other side\nNemo judex in causa sua → No one should be judge in their own cause\nArticle 14 → Equality before law\nManeka Gandhi case, 1978 → Expanded interpretation of Article 21."},
{"no":32,"text":"Consider the following statements:\nStatement-I: In India, prisons are managed by State Governments with their own rules and regulations for the day-to-day administration of prisons.\nStatement-II: In India, prisons are governed by the Prisons Act, 1894 which expressly kept the subject of prisons in the control of Provincial Governments.\nWhich one of the following is correct?","A":"Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I.","B":"Both Statement-I and Statement-II are correct but Statement-II is not the correct explanation for Statement-I.","C":"Statement-I is correct but Statement-II is incorrect.","D":"Statement-I is incorrect but Statement-II is correct.","ans":"A","category":"Polity & Governance","subcategory":"Centre-State Relations","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nPrisons are primarily administered by State Governments.\nStates have their own rules and regulations for prison administration.\nStatement-II — Correct\nThe Prisons Act, 1894 provided for prison administration under the control of the then Provincial Governments.\nTherefore:\nStatement-I → ✅\nStatement-II → ✅\nStatement-II explains Statement-I → ✅","revisionPoints":"Prisons → State List\nPrison administration → Primarily State responsibility.\nImportant law:\nPrisons Act, 1894\nState Governments:\nManage prisons\nFrame prison rules\nHandle day-to-day administration\nSeventh Schedule → State List"},
{"no":33,"text":"Which one of the following statements best reflects the chief purpose of the ‘Constitution’ of a country?","A":"It determines the objective for the making of necessary laws.","B":"It enables the creation of political offices and a government.","C":"It defines and limits the powers of government.","D":"It secures social justice, social equality and social security.","ans":"C","category":"Polity & Governance","subcategory":"Constitution","tags":["UPSC","2023"],"expl":"The Constitution establishes the basic framework of government.\nIt defines:\nPowers of government\nFunctions of institutions\nLimits on governmental authority\nRights of citizens\nA key purpose of constitutionalism is to prevent arbitrary exercise of governmental power.\nOther options describe functions that a Constitution may perform, but the central purpose is to define and limit government power.","revisionPoints":"Constitution → Supreme legal framework\nDefines powers of:\nLegislature\nExecutive\nJudiciary\nLimits government power.\nProtects fundamental rights.\nEstablishes institutional structure.\nProvides principles for governance.\nConstitutionalism → Limited government + rule of law"},
{"no":34,"text":"In India, which one of the following Constitutional Amendments was widely believed to be enacted to overcome the judicial interpretations of the Fundamental Rights?","A":"1st Amendment","B":"42nd Amendment","C":"44th Amendment","D":"86th Amendment","ans":null,"dropped":true,"category":"Polity & Governance","subcategory":"Constitutional Amendment","tags":["UPSC","2023"],"expl":"The question was considered problematic because both the 1st Amendment and 42nd Amendment can be connected with attempts to respond to judicial interpretations affecting Fundamental Rights.\nThe 1st Constitutional Amendment, 1951 directly responded to early judicial decisions involving:\nFreedom of speech\nLand reform\nReservations\nIt introduced:\nArticle 15(4)\nArticles 31A and 31B\nNinth Schedule\nChanges to restrictions under Article 19\nThe 42nd Amendment, 1976 also sought to substantially alter the balance between Parliament, Fundamental Rights and judicial review.\nBecause of this ambiguity, UPSC dropped the question.","revisionPoints":"1st Amendment — 1951\nArticle 15(4)\nArticles 31A and 31B\nNinth Schedule\nRestrictions under Article 19\n42nd Amendment — 1976\nKnown as the “Mini-Constitution”\nAdded:\nSocialist\nSecular\nIntegrityto the Preamble\nAdded Fundamental Duties.\nMade several changes affecting Centre-State relations and judicial review.\n44th Amendment — 1978\nReversed several Emergency-era changes.\nRight to Property removed from Fundamental Rights.\n86th Amendment — 2002\nIntroduced Article 21A\nRight to Education."},
{"no":35,"text":"Consider the following organisations/bodies in India:\nThe National Commission for Backward Classes\nThe National Human Rights Commission\nThe National Law Commission\nThe National Consumer Disputes Redressal Commission\nHow many of the above are constitutional bodies?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"A","category":"Polity & Governance","subcategory":"Government Bodies","tags":["UPSC","2023"],"expl":"National Commission for Backward Classes — Constitutional body\nGiven constitutional status through the 102nd Constitutional Amendment Act, 2018.\nArticle 338B deals with the NCBC.\nNational Human Rights Commission — Statutory body\nEstablished under the Protection of Human Rights Act, 1993.\nNational Law Commission — Executive body\nCreated by government resolution/notification.\nNot a constitutional body.\nNational Consumer Disputes Redressal Commission — Statutory body\nEstablished under consumer protection legislation.\nTherefore, only NCBC is a constitutional body.","revisionPoints":"NCBC → Constitutional\n102nd Amendment, 2018\nArticle 338B\nNHRC → Statutory\nProtection of Human Rights Act, 1993\nLaw Commission → Executive body\nNCDRC → Statutory\nImportant distinction\nConstitutional body → Created directly by Constitution\nStatutory body → Created by an Act of Parliament\nExecutive body → Created by government executive action"},
{"no":36,"text":"Consider the following statements:\nIf the election of the President of India is declared void by the Supreme Court of India, all acts done by him/her in the performance of duties of his/her office of President before the date of decision become invalid.\nElection for the post of the President of India can be postponed on the ground that some Legislative Assemblies have been dissolved and elections are yet to take place.\nWhen a Bill is presented to the President of India, the Constitution prescribes time limits within which he/she has to declare his/her assent.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"D","category":"Polity & Governance","subcategory":"President","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nEven if the President's election is declared void, acts performed in the discharge of presidential duties before the Supreme Court's decision do not automatically become invalid.\nThis protects continuity of constitutional government.\nStatement 2 — Incorrect\nPresidential election cannot simply be postponed because some State Legislative Assemblies have been dissolved.\nThe constitutional process ensures continuity of the office of President.\nStatement 3 — Incorrect\nThe Constitution does not prescribe a specific time limit within which the President must give assent to a Bill.\nTherefore:\nStatement 1 → ❌\nStatement 2 → ❌\nStatement 3 → ❌","revisionPoints":"President's election → Constitutional process.\nElectoral College includes:\nElected MPs\nElected MLAs of States\nElected MLAs of Delhi and Puducherry\nPresident's assent to Bills:\nAssent\nWithhold assent\nReturn a non-Money Bill for reconsideration\nConstitution does not prescribe a specific number of days for presidential assent."},
{"no":37,"text":"With reference to Finance Bill and Money Bill in the Indian Parliament, consider the following statements:\nWhen the Lok Sabha transmits Finance Bill to the Rajya Sabha, it can amend or reject the Bill.\nWhen the Lok Sabha transmits Money Bill to the Rajya Sabha, it cannot amend or reject the Bill, it can only make recommendations.\nIn the case of disagreement between the Lok Sabha and the Rajya Sabha, there is no joint sitting for Money Bill, but a joint sitting becomes necessary for Finance Bill.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"B","category":"Polity & Governance","subcategory":"Parliament","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nIn the context of the Finance Bill associated with the Budget, the Rajya Sabha does not have the same power as Lok Sabha to amend or reject it.\nIts role is restricted.\nStatement 2 — Correct\nA Money Bill can originate only in the Lok Sabha.\nRajya Sabha:\nCannot amend it.\nCannot reject it.\nCan only make recommendations.\nIt must return the Bill within 14 days.\nStatement 3 — Correct\nThere is no joint sitting for a Money Bill.\nA joint sitting can apply to certain other legislative deadlocks, including relevant Financial Bills.\nTherefore:\nStatement 1 → ❌\nStatement 2 → ✅\nStatement 3 → ✅","revisionPoints":"Money Bill — Article 110\nCan originate only in Lok Sabha.\nRajya Sabha can only recommend changes.\nRecommendations must be made within 14 days.\nSpeaker certifies whether a Bill is a Money Bill.\nNo joint sitting for Money Bills.\nFinance Bill\nDeals with taxation and financial proposals.\nThe exact parliamentary procedure depends on its constitutional classification."},
{"no":38,"text":"Once the Central Government notifies an area as a ‘Community Reserve’:\nThe Chief Wildlife Warden of the State becomes the governing authority of such forest.\nHunting is not allowed in such area.\nPeople of such area are allowed to collect non-timber forest produce.\nPeople of such area are allowed traditional agricultural practices.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"C","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nThe Chief Wildlife Warden does not become the governing authority of the Community Reserve.\nStatement 2 — Correct\nHunting is prohibited in a Community Reserve.\nStatement 3 — Correct\nLocal people can collect non-timber forest produce, subject to applicable regulations.\nStatement 4 — Correct\nTraditional agricultural practices of local communities can continue.\nTherefore:\nStatement 1 → ❌\nStatement 2 → ✅\nStatement 3 → ✅\nStatement 4 → ✅","revisionPoints":"Community Reserve → Protected Area category\nCreated on:\nPrivate land\nCommunity land\nIntended to protect:\nWildlife\nBiodiversity\nLocal ecological values\nLocal communities retain certain traditional rights and practices.\nHunting is prohibited.\nCommunity participation is an important feature."},
{"no":39,"text":"With reference to ‘Scheduled Areas’ in India, consider the following statements:\nWithin a State, the notification of an area as Scheduled Area takes place through an Order of the President.\nThe largest administrative unit forming the Scheduled Area is the District and the lowest is the cluster of villages in the Block.\nThe Chief Ministers of the concerned States are required to submit annual reports to the Union Home Ministry on the administration of Scheduled Areas in the States.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"B","category":"Polity & Governance","subcategory":"Constitution","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nUnder the Fifth Schedule, the President can declare an area as a Scheduled Area through an order.\nStatement 2 — Correct\nThe district is the largest administrative unit forming Scheduled Areas.\nThe lowest is the cluster of villages in the Block.\nStatement 3 — Incorrect\nIt is the Governor, not the Chief Minister, who submits the annual report.\nThe report is made to the President regarding administration of Scheduled Areas.\nTherefore:\nStatement 1 → ✅\nStatement 2 → ✅\nStatement 3 → ❌","revisionPoints":"Scheduled Areas → Fifth Schedule\nConstitutional basis:\nArticle 244(1)\nFifth Schedule\nPresident:\nDeclares Scheduled Areas.\nCan alter/increase/decrease the area.\nGovernor:\nHas special responsibilities regarding administration.\nSubmits annual report to the President.\nFifth Schedule → Scheduled Areas\nSixth Schedule → Tribal Areas in Assam, Meghalaya, Tripura and Mizoram"},
{"no":40,"text":"Consider the following statements:\nStatement-I: The Supreme Court of India has held in some judgements that the reservation policies made under Article 16(4) of the Constitution of India would be limited by Article 335 for maintenance of efficiency of administration.\nStatement-II: Article 335 of the Constitution of India defines the term ‘efficiency of administration’.\nWhich one of the following is correct?","A":"Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I.","B":"Both Statement-I and Statement-II are correct but Statement-II is not the correct explanation for Statement-I.","C":"Statement-I is correct but Statement-II is incorrect.","D":"Statement-I is incorrect but Statement-II is correct.","ans":"C","category":"Polity & Governance","subcategory":"Fundamental Rights","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nThe Supreme Court has considered the relationship between:\nReservation under Article 16(4)\nEfficiency of administration under Article 335\nJudicial decisions have discussed the need to balance reservation with administrative efficiency.\nStatement-II — Incorrect\nArticle 335 does not define the term “efficiency of administration”.\nIt only states that the claims of SCs and STs should be considered consistently with the maintenance of efficiency of administration.\nTherefore:\nStatement-I → ✅\nStatement-II → ❌","revisionPoints":"Article 16(4)\nEnables reservation in public employment for backward classes that are inadequately represented.\nArticle 335\nDeals with claims of SCs and STs in public services.\nRequires consideration consistent with efficiency of administration.\nImportant cases:\nIndra Sawhney case, 1992\nM. Nagaraj case, 2006\nArticle 16 → Equality of opportunity in public employment\nArticle 335 → SC/ST claims + efficiency of administration"},
{"no":41,"text":"In which one of the following regions was Dhanyakataka, a prominent Buddhist centre under the Mahasanghikas, located?","A":"Andhra","B":"Gandhara","C":"Kalinga","D":"Magadha","ans":"A","category":"History","subcategory":"Ancient India","tags":["UPSC","2023"],"expl":"Dhanyakataka was an important Buddhist centre in the Andhra region.\nIt was associated with the Mahasanghika tradition.\nIt was located in the broader Krishna valley.\nThe region was also associated with Amaravati Buddhist art and architecture.","revisionPoints":"Dhanyakataka → Andhra\nMahasanghika → important Buddhist association\nKrishna valley → important Buddhist region\nAmaravati → major Buddhist centre\nOther important centres:\nSarnath → Uttar Pradesh\nBodh Gaya → Bihar\nSanchi → Madhya Pradesh\nGandhara → Northwestern subcontinent"},
{"no":42,"text":"With reference to ancient India, consider the following statements:\nThe concept of Stupa is Buddhist in origin.\nStupa was generally a repository of relics.\nStupa was a votive and commemorative structure in Buddhist tradition.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"C","category":"History","subcategory":"Ancient India","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nThe stupa became an important architectural form in Buddhist tradition.\nStatement 2 — Correct\nStupas could contain or commemorate relics associated with the Buddha or Buddhist sacred persons.\nStatement 3 — Correct\nStupas served as votive and commemorative monuments and became important centres of Buddhist worship.","revisionPoints":"Stupa → relics + worship + commemoration\nChaitya → prayer/worship hall\nVihara → monastery/residence\nTorana → gateway, prominently seen at Sanchi\nStupa should not be understood merely as a tomb."},
{"no":43,"text":"With reference to ancient South India, Korkai, Poompuhar and Muchiri were well known as:","A":"Capital cities","B":"Ports","C":"Centres of iron-and-steel making","D":"Shrines of Jain Tirthankaras","ans":"B","category":"History","subcategory":"Ancient India","tags":["UPSC","2023"],"expl":"Korkai\nAssociated with the Pandya region.\nImportant for pearl fishing and maritime trade.\nPoompuhar\nAlso known as Kaveripattinam.\nImportant Chola port.\nMuchiri\nAlso known as Muziris.\nAssociated with the Chera region.\nImportant centre of overseas trade.","revisionPoints":"Korkai → Pandya\nPoompuhar/Kaveripattinam → Chola\nMuchiri/Muziris → Chera\nMajor trade goods:\nPearls\nSpices\nTextiles\nPrecious goods"},
{"no":44,"text":"Which one of the following explains the practice of \"Vattakirutal\" mentioned in Sangam poems?","A":"Kings employing women bodyguards","B":"Learned persons assembling in royal courts to discuss religious and philosophical matters","C":"Young girls keeping watch over agricultural fields and driving away birds and animals","D":"A king defeated in a battle committing ritual suicide by starving himself to death","ans":"D","category":"History","subcategory":"Ancient India","tags":["UPSC","2023"],"expl":"Vattakirutal refers to a practice in which a defeated king undertook ritual death by fasting.\nIt reflected aspects of the warrior ethos described in Sangam literature.\nImportant associated ideas:\nHonour\nMartial reputation\nShame associated with defeat\nWarrior ethics","revisionPoints":"Sangam literature provides information about:\nKingship\nWarfare\nTrade\nAgriculture\nSocial life\nReligious practices\nHeroic traditions"},
{"no":45,"text":"Consider the following dynasties:\nHoysala\nGahadavala\nKakatiya\nYadava\nHow many of the above dynasties established their kingdoms in early eighth century AD?","A":"Only one","B":"Only two","C":"Only three","D":"None","ans":"D","category":"History","subcategory":"Medieval India","tags":["UPSC","2023"],"expl":"None of these dynasties established their kingdoms in the early eighth century AD.\nTheir major political prominence came considerably later.\nHoysala → mainly 11th–14th centuries\nGahadavala → mainly 11th–12th centuries\nKakatiya → mainly 12th–14th centuries\nYadava of Devagiri → mainly 12th–14th centuries","revisionPoints":"Hoysala → Southern India\nGahadavala → Northern India\nKakatiya → Deccan\nYadava → Devagiri\nUse a chronological timeline to distinguish medieval dynasties."},
{"no":46,"text":"Consider the following pairs:\nLiterary Work\nAuthor\n1. Devichandragupta\nBilhana\n2. Hammira-Mahakavya\nNayachandra Suri\n3. Milinda-panha\nNagarjuna\n4. Nitivakyamrita\nSomadeva Suri\nHow many pairs are correctly matched?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"B","category":"History","subcategory":"Ancient India","tags":["UPSC","2023"],"expl":"Pair 1 — Incorrect\nDevichandragupta → associated with Vishakhadatta, not Bilhana.\nPair 2 — Correct\nHammira-Mahakavya → Nayachandra Suri\nPair 3 — Incorrect\nMilinda-panha presents a dialogue between King Menander (Milinda) and Nagasena.\nPair 4 — Correct\nNitivakyamrita → Somadeva Suri","revisionPoints":"Mudrarakshasa → Vishakhadatta\nHammira-Mahakavya → Nayachandra Suri\nNitivakyamrita → Somadeva Suri\nMilinda-panha → Menander–Nagasena dialogue\nMemorise author + work + period + subject."},
{"no":47,"text":"\"Souls are not only the property of animal and plant life, but also of rocks, running water and many other natural objects not looked on as living by other religious sects.\"\nThe above statement reflects one of the core beliefs of which ancient Indian religion?","A":"Buddhism","B":"Jainism","C":"Shaivism","D":"Vaishnavism","ans":"B","category":"History","subcategory":"Ancient India","tags":["UPSC","2023"],"expl":"The statement reflects the Jain concept of Jiva.\nJain philosophy has a broad understanding of living entities.\nThis idea is closely connected with Ahimsa.\nIf life is recognised in many forms, avoiding harm becomes an important ethical principle.","revisionPoints":"Jiva → living/soul\nAjiva → non-living\nAhimsa → non-violence\nAnekantavada → many-sidedness of reality\nAparigraha → non-possession"},
{"no":48,"text":"Who among the following rulers of Vijayanagara Empire constructed a large dam across Tungabhadra River and a canal-cum-aqueduct several kilometres long from the river to the capital city?","A":"Devaraya I","B":"Mallikarjuna","C":"Vira Vijaya","D":"Virupaksha","ans":"A","category":"History","subcategory":"Medieval India","tags":["UPSC","2023"],"expl":"Devaraya I is associated with major irrigation works in the Vijayanagara Empire.\nA dam was constructed across the Tungabhadra River.\nA canal-cum-aqueduct carried water towards the capital.\nThis demonstrates the importance of hydraulic engineering in supporting Vijayanagara's urban and agricultural economy.","revisionPoints":"Tungabhadra → Vijayanagara/Hampi\nVijayanagara prosperity depended on:\nIrrigation\nTanks\nCanals\nDams\nRiver water\nAgricultural surplus"},
{"no":49,"text":"Who among the following rulers of medieval Gujarat surrendered Diu to the Portuguese?","A":"Ahmad Shah","B":"Mahmud Begarha","C":"Bahadur Shah","D":"Muhammad Shah","ans":"C","category":"History","subcategory":"Medieval India","tags":["UPSC","2023"],"expl":"Bahadur Shah of Gujarat came into conflict with the Portuguese during the 16th century.\nThe Portuguese obtained important strategic advantages at Diu.\nDiu was strategically important because of its location along the Arabian Sea maritime trade routes.","revisionPoints":"Portuguese strategic centres included:\nGoa\nDiu\nDaman\nOther coastal settlements\nImportant theme:\nPortuguese expansion → maritime trade → naval power → fortified coastal settlements"},
{"no":50,"text":"By which one of the following Acts was the Governor General of Bengal designated as the Governor General of India?","A":"The Regulating Act","B":"Pitt's India Act","C":"Charter Act of 1793","D":"Charter Act of 1833","ans":"D","category":"History","subcategory":"Modern India","tags":["UPSC","2023"],"expl":"The Charter Act of 1833 designated the Governor-General of Bengal as the Governor-General of India.\nLord William Bentinck became the first Governor-General of India under this arrangement.\nThe Act also:\nCentralised legislative authority.\nEnded the East India Company's commercial activities.\nStrengthened central administration.","revisionPoints":"Charter Act 1813\nEnded most of Company's trade monopoly.\nMonopoly continued mainly in tea and China trade.\nCharter Act 1833\nGovernor-General of Bengal → Governor-General of India.\nCentralisation of legislative power.\nCompany ceased commercial activities.\nCharter Act 1853\nFurther legislative changes.\nOpen competition principle associated with civil services."},
{"no":51,"text":"Consider the following statements:\nIt is a safe motherhood intervention of the State Health Departments.\nIts objective is to reduce maternal and neonatal mortality among poor pregnant women.\nIt aims to promote institutional delivery among poor pregnant women.\nIts objective includes providing public health facilities to sick infants up to one year of age.\nHow many of the statements given above are correct?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"C","category":"Economy","subcategory":"Government Schemes","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nJSY is a safe motherhood intervention under the National Health Mission.\nStatement 2 — Correct\nIt aims to reduce maternal and neonatal mortality among poor and vulnerable pregnant women.\nStatement 3 — Correct\nIt promotes institutional delivery.\nStatement 4 — Incorrect\nHealthcare for sick infants is associated with other maternal and child-health programmes, not the core objective of JSY.","revisionPoints":"JSY → Safe motherhood → Institutional delivery → Reduced maternal/neonatal mortality\nDon't confuse JSY with:\nJSSK\nOther maternal and child-health programmes."},
{"no":52,"text":"Consider the following interventions:\nProphylactic calcium supplementation\nDelayed cord clamping\nPeriodic deworming\nAddressing non-nutritional causes like malaria, haemoglobinopathies and fluorosis\nHow many statements are correct?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"C","category":"Economy","subcategory":"Government Schemes","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nProphylactic calcium supplementation is not a core intervention of Anaemia Mukt Bharat.\nStatement 2 — Correct\nDelayed cord clamping can improve infant iron stores.\nStatement 3 — Correct\nPeriodic deworming helps address parasitic infections contributing to anaemia.\nStatement 4 — Correct\nAMB recognises non-nutritional causes such as:\nMalaria\nHaemoglobinopathies\nOther conditions","revisionPoints":"Anaemia Mukt Bharat approach:\nIron/folic acid\nDeworming\nBehaviour change\nTesting and treatment\nAddressing non-nutritional causes\nAnaemia ≠ only iron deficiency."},
{"no":53,"text":"Consider the following statements:\nCarbon fibres are used in the manufacture of components used in automobiles and aircrafts.\nCarbon fibres once used cannot be recycled.","A":"1 only","B":"2 only","C":"Both 1 and 2","D":"Neither 1 nor 2","ans":"A","category":"Science & Technology","subcategory":"Materials Science","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nCarbon fibre has:\nHigh strength-to-weight ratio\nHigh stiffness\nLow density\nTherefore, it is useful in:\nAircraft\nAutomobiles\nSports equipment\nEngineering structures\nStatement 2 — Incorrect\nCarbon-fibre-reinforced composites can be recycled.\nRecycling is technically challenging but not impossible.","revisionPoints":"Carbon fibre → high strength + low weight\nApplications:\nAerospace\nAutomobiles\nDefence\nSports equipment\nImportant distinction:\nDifficult to recycle ≠ impossible to recycle"},
{"no":54,"text":"Consider the following actions:\nCar crash detection deploying airbags\nLaptop free-fall detection\nSmartphone auto screen rotation\nIn how many of the above actions is an accelerometer required?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"C","category":"Science & Technology","subcategory":"IT & Computers","tags":["UPSC","2023"],"expl":"Car crash detection\nSudden acceleration/deceleration can indicate a collision.\nLaptop free-fall detection\nAccelerometers detect rapid changes associated with free fall.\nSmartphone auto screen rotation\nAccelerometers detect changes in orientation relative to gravity.\nTherefore, all three involve accelerometer-based sensing.","revisionPoints":"Accelerometer → acceleration + movement + orientation\nApplications:\nSmartphones\nVehicles\nAircraft\nWearables\nGaming devices\nSafety systems\nRemember:\nAccelerometer → acceleration\nGyroscope → angular velocity/rotation"},
{"no":55,"text":"With reference to the role of biofilters in Recirculating Aquaculture System (RAS), consider the following statements:\nRemove uneaten fish feed.\nConvert ammonia into nitrate.\nIncrease phosphorus as nutrient for fish.\nHow many statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"A","category":"Science & Technology","subcategory":"Biotechnology","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nBiofilters primarily treat dissolved biological wastes, especially nitrogenous compounds.\nThey are not primarily designed to remove uneaten feed.\nStatement 2 — Correct\nNitrifying bacteria convert:\nAmmonia → Nitrite → Nitrate\nStatement 3 — Incorrect\nBiofilters are not intended to increase phosphorus as a nutrient for fish.","revisionPoints":"RAS → Treat → Recirculate → Reuse water\nBiofilters help control:\nAmmonia\nNitrite\nOther nitrogenous wastes\nImportant sequence:\nAmmonia → Nitrite → Nitrate"},
{"no":56,"text":"Consider the following pairs:\nObject\nDescription\n1. Cepheids\nGiant clouds of dust and gas\n2. Nebulae\nStars which brighten and dim periodically\n3. Pulsars\nNeutron stars formed after collapse of massive stars\nHow many pairs are correctly matched?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"A","category":"Science & Technology","subcategory":"Space","tags":["UPSC","2023"],"expl":"Pair 1 — Incorrect\nCepheids are variable stars, not clouds of gas and dust.\nPair 2 — Incorrect\nNebulae are clouds of gas and dust.\nPeriodically brightening/dimming stars are variable stars, including Cepheids.\nPair 3 — Correct\nPulsars are rapidly rotating neutron stars emitting beams of electromagnetic radiation.","revisionPoints":"Cepheid → pulsating variable star\nNebula → cloud of gas and dust\nPulsar → rapidly rotating neutron star"},
{"no":57,"text":"Which one of the following countries has its own Satellite Navigation System?","A":"Australia","B":"Canada","C":"Israel","D":"Japan","ans":"D","category":"Science & Technology","subcategory":"Space","tags":["UPSC","2023"],"expl":"Japan operates the Quasi-Zenith Satellite System (QZSS).\nQZSS provides positioning services particularly suited to the Japanese region.\nIt complements global satellite-navigation systems.","revisionPoints":"USA → GPS\nRussia → GLONASS\nEuropean Union → Galileo\nChina → BeiDou\nIndia → NavIC\nJapan → QZSS\nQZSS → strong regional focus"},
{"no":58,"text":"Consider the following statements:\nBallistic missiles are jet-propelled throughout flight while cruise missiles are rocket-powered only in the initial phase.\nAgni-V is a medium-range supersonic cruise missile, while BrahMos is a solid-fuelled intercontinental ballistic missile.","A":"1 only","B":"2 only","C":"Both 1 and 2","D":"Neither 1 nor 2","ans":"D","category":"Science & Technology","subcategory":"Defence Technology","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nBallistic missiles are generally powered during an initial boost phase and then follow a ballistic trajectory.\nCruise missiles remain powered through much of their flight and fly within the atmosphere.\nStatement 2 — Incorrect\nThe identities are reversed:\nAgni-V → ballistic missile\nBrahMos → supersonic cruise missile","revisionPoints":"Ballistic missile\nBoost phase\nHigh trajectory\nBallistic/re-entry phase\nCruise missile\nPowered flight\nAtmospheric flight\nAerodynamic lift\nMemory association:\nAgni → BallisticBrahMos → Cruise"},
{"no":59,"text":"Consider the following statements:\nGold mining is a source of mercury pollution.\nCoal-based thermal power plants cause mercury pollution.\nThere is no known safe level of mercury exposure.\nHow many statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"C","category":"Environment & Ecology","subcategory":"Pollution","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nMercury is used in some forms of artisanal and small-scale gold mining.\nStatement 2 — Correct\nCoal combustion can release mercury naturally present in coal.\nStatement 3 — Correct\nMercury is toxic and can affect:\nNervous system\nKidneys\nDevelopment\nFoetal health","revisionPoints":"Major mercury sources:\nArtisanal gold mining\nCoal combustion\nCertain industrial processes\nImportant international agreement:\nMinamata Convention on Mercury"},
{"no":60,"text":"With reference to green hydrogen, consider the following statements:\nIt can be used directly as a fuel.\nIt can be blended with natural gas.\nIt can be used in hydrogen fuel-cell vehicles.\nHow many statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"C","category":"Science & Technology","subcategory":"Renewable Energy","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nHydrogen can be used as a fuel in suitable combustion and industrial applications.\nStatement 2 — Correct\nHydrogen can be blended with natural gas in suitable systems, subject to technical limitations.\nStatement 3 — Correct\nHydrogen fuel cells generate electricity through an electrochemical reaction with oxygen.\nGreen hydrogen generally refers to hydrogen produced through electrolysis using renewable electricity.","revisionPoints":"Green hydrogen → renewable electricity + electrolysis\nGrey hydrogen → fossil-fuel-based production without carbon capture\nBlue hydrogen → fossil-fuel-based production with carbon capture\nBrown/black hydrogen → coal-based production\nThe production method determines the colour classification of hydrogen."},
{"no":61,"text":"Consider the following countries:\nBulgaria\nCzech Republic\nHungary\nLatvia\nLithuania\nRomania\nHow many of the above countries share a land border with Ukraine?","A":"Only two","B":"Only three","C":"Only four","D":"Only five","ans":"A","category":"Geography","subcategory":"Physical Geography","tags":["UPSC","2023"],"expl":"The supplied source lists Ukraine's land neighbours as:\nHungary\nRomania\nSlovakia\nPoland\nMoldova\nBelarus\nRussia\nFrom the countries given:\nBulgaria ❌\nCzech Republic ❌\nHungary ✅\nLatvia ❌\nLithuania ❌\nRomania ✅\nTherefore, only two of the listed countries actually border Ukraine.","revisionPoints":"Ukraine borders:\nRussia\nBelarus\nPoland\nSlovakia\nHungary\nRomania\nMoldova\nHungary + Romania are the only two countries from the six given that border Ukraine."},
{"no":62,"text":"With reference to the Earth's atmosphere, which one of the following statements is correct?","A":"The equator receives only about 10 times the insolation received at the poles.","B":"Infrared rays constitute roughly two-thirds of insolation.","C":"Infrared waves are largely absorbed by water vapour concentrated in the lower atmosphere.","D":"Infrared waves are part of the visible spectrum of solar radiation.","ans":"C","category":"Geography","subcategory":"Physical Geography","tags":["UPSC","2023"],"expl":"Infrared radiation is part of the electromagnetic spectrum.\nIt is not part of visible light.\nWater vapour is an important absorber of infrared radiation in the atmosphere.\nInfrared radiation is also important in Earth's terrestrial radiation and greenhouse effect.","revisionPoints":"Sun → mainly shortwave radiation\nEarth → mainly longwave/infrared radiation\nImportant greenhouse gases:\nWater vapour\nCO₂\nMethane\nNitrous oxide\nOzone\nInfrared → invisible portion of electromagnetic spectrum."},
{"no":63,"text":"Statement-I: The soil in tropical rain forests is rich in nutrients.\nStatement-II: The high temperature and moisture of tropical rain forests cause dead organic matter in the soil to decompose quickly.","A":"Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I.","B":"Both Statement-I and Statement-II are correct but Statement-II is not the correct explanation for Statement-I.","C":"Statement-I is correct but Statement-II is incorrect.","D":"Statement-I is incorrect but Statement-II is correct.","ans":"D","category":"Geography","subcategory":"Physical Geography","tags":["UPSC","2023"],"expl":"Statement-I — Incorrect\nTropical rainforest soils are generally not highly nutrient-rich.\nHeavy rainfall causes intense leaching.\nVegetation rapidly absorbs available nutrients.\nStatement-II — Correct\nHigh temperature + moisture → rapid decomposition of organic matter.\nTherefore:\nI ❌\nII ✅","revisionPoints":"Tropical rainforest:\nHigh rainfall → leaching\nHigh temperature + moisture → rapid decomposition\nDense vegetation → rapid nutrient uptake\nHigh forest productivity does not necessarily mean highly fertile soil."},
{"no":64,"text":"Statement-I: The temperature contrast between continents and oceans is greater during summer than in winter.\nStatement-II: The specific heat of water is more than that of land surface.","A":"Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I.","B":"Both Statement-I and Statement-II are correct but Statement-II is not the correct explanation for Statement-I.","C":"Statement-I is correct but Statement-II is incorrect.","D":"Statement-I is incorrect but Statement-II is correct.","ans":"A","category":"Geography","subcategory":"Physical Geography","tags":["UPSC","2023"],"expl":"Both statements are correct.\nWater has a higher specific heat capacity than land.\nLand heats and cools faster.\nDuring summer:\nLand heats rapidly.\nOcean heats more slowly.\nTemperature contrast increases.\nThus, Statement-II explains Statement-I.","revisionPoints":"Land → heats quickly + cools quickly.\nWater → heats slowly + cools slowly.\nCoastal areas generally experience moderated temperatures.\nHigh specific heat → slower temperature change."},
{"no":65,"text":"Consider the following statements:\nIn a seismograph, P waves are recorded earlier than S waves.\nIn P waves, particles vibrate parallel to the direction of propagation, whereas in S waves they vibrate perpendicular to the direction of propagation.","A":"1 only","B":"2 only","C":"Both 1 and 2","D":"Neither 1 nor 2","ans":"C","category":"Geography","subcategory":"Physical Geography","tags":["UPSC","2023"],"expl":"P waves\nPrimary waves.\nFastest seismic waves.\nArrive first.\nParticle movement is parallel to propagation.\nS waves\nSecondary waves.\nSlower than P waves.\nParticle movement is perpendicular to propagation.\nCannot travel through liquids.","revisionPoints":"Wave\nSpeed\nParticle movement\nLiquid\nP\nFaster\nParallel\nCan travel\nS\nSlower\nPerpendicular\nCannot travel\nP = Primary = first.\nS = Secondary = second."},
{"no":66,"text":"With reference to coal-based thermal power plants in India:\nNone of them uses seawater.\nNone of them is set up in a water-stressed district.\nNone of them is privately owned.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"D","category":"Environment & Ecology","subcategory":"Pollution","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nSome coastal thermal power plants use seawater for cooling.\nStatement 2 — Incorrect\nThermal power plants can exist in water-stressed regions.\nStatement 3 — Incorrect\nIndia has privately owned coal-based thermal power plants.\nTherefore, none of the statements is correct.","revisionPoints":"Thermal power plants can involve:\nWater consumption\nThermal pollution\nFly ash\nAir pollution\nCO₂ emissions\nMercury and other pollutants"},
{"no":67,"text":"'Wolbachia method' is sometimes talked about with reference to which one of the following?","A":"Controlling the viral diseases spread by mosquitoes","B":"Converting crop residues into packing material","C":"Producing biodegradable plastics","D":"Producing biochar from thermochemical conversion of biomass","ans":"A","category":"Science & Technology","subcategory":"Biotechnology","tags":["UPSC","2023"],"expl":"Wolbachia is a naturally occurring bacterium found in certain insects.\nWolbachia-infected mosquitoes can have reduced ability to transmit certain viruses.\nIt has been studied/used in controlling mosquito-borne diseases.","revisionPoints":"Wolbachia → bacterium\nAssociated with reduced transmission of:\nDengue\nZika\nChikungunya\nYellow fever\nIt is a biological approach, not a conventional chemical pesticide."},
{"no":68,"text":"Consider the following activities:\nSpreading finely ground basalt rock on farmlands.\nIncreasing the alkalinity of oceans by adding lime.\nCapturing carbon dioxide from industries and pumping it into abandoned underground mines in the form of carbonated waters.\nHow many of the above activities are often considered and discussed for carbon capture and sequestration?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"C","category":"Environment & Ecology","subcategory":"Climate Change","tags":["UPSC","2023"],"expl":"1 — Enhanced rock weathering\nBasalt can react with CO₂ and contribute to carbon storage.\n2 — Ocean alkalinity enhancement\nIncreasing alkalinity can increase the ocean's capacity to absorb CO₂.\n3 — Underground carbon storage\nCO₂ can potentially be stored underground or converted into stable carbonate forms.","revisionPoints":"Carbon capture → capturing CO₂ from a source.\nCarbon removal → removing CO₂ from the atmosphere.\nCarbon sequestration/storage → keeping carbon in a stable reservoir.\nApproaches include:\nForests\nSoils\nMineralisation\nGeological storage\nOcean-based approaches"},
{"no":69,"text":"'Aerial metagenomics' best refers to which one of the following situations?","A":"Collecting DNA samples from air in a habitat at one go","B":"Understanding the genetic makeup of avian species of a habitat","C":"Using air-borne devices to collect blood samples from moving animals","D":"Sending drones to inaccessible areas to collect plant and animal samples from land surfaces and water bodies","ans":"A","category":"Science & Technology","subcategory":"Biotechnology","tags":["UPSC","2023"],"expl":"Metagenomics studies genetic material obtained directly from environmental samples.\nAerial metagenomics involves collecting genetic material present in the air.\nAir can contain:\nMicrobial DNA\nPollen\nPlant material\nAnimal DNA\nOther biological particles","revisionPoints":"Metagenomics → environmental genetic material.\nApplications:\nBiodiversity monitoring\nPathogen detection\nEcosystem assessment\nEnvironmental surveillance\n“Aerial” here refers to the airborne environment, not necessarily drones."},
{"no":70,"text":"'Microsatellite DNA' is used in the case of which one of the following?","A":"Studying the evolutionary relationships among various species of fauna","B":"Stimulating stem cells to transform into diverse functional tissues","C":"Promoting clonal propagation of horticultural plants","D":"Assessing the efficacy of drugs by conducting a series of drug trials in a population","ans":"A","category":"Science & Technology","subcategory":"Biology","tags":["UPSC","2023"],"expl":"Microsatellites are short, repeated DNA sequences.\nTheir variation between individuals makes them useful as genetic markers.\nThey are used in:\nPopulation genetics\nGenetic diversity studies\nEvolutionary studies\nConservation genetics\nParentage analysis","revisionPoints":"Microsatellite DNA → genetic marker\nUseful for:\nPopulation genetics\nBiodiversity\nEvolutionary relationships\nConservation studies"},
{"no":71,"text":"Consider the following statements:\nAccording to the MSMED Act, 2006, the 'medium enterprises' are those with investments in plant and machinery between ₹15 crore and ₹25 crore.\nAll bank loans to the Micro, Small and Medium Enterprises qualify under the priority sector.","A":"1 only","B":"2 only","C":"Both 1 and 2","D":"Neither 1 nor 2","ans":"B","category":"Economy","subcategory":"Corporate Regulation","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nThe classification stated does not correctly represent the applicable MSME classification.\nMSME classification has subsequently changed.\nStatement 2 — Correct in the intended framework\nMSMEs form an important category under Priority Sector Lending, subject to applicable RBI rules.","revisionPoints":"Priority Sector Lending includes areas such as:\nAgriculture\nMSMEs\nEducation\nHousing\nRenewable energy\nSpecified export credit\nOther RBI-specified sectors\nAlways identify the year and classification framework when studying MSMEs."},
{"no":72,"text":"Consider the following statements:\nIt is possible to make payments in a digital currency without using the US dollar or SWIFT system.\nA digital currency can be distributed with a condition programmed into it, such as a time-frame for spending it.","A":"1 only","B":"2 only","C":"Both 1 and 2","D":"Neither 1 nor 2","ans":"C","category":"Economy","subcategory":"Banking","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nCBDC is digital sovereign money issued by a central bank.\nIts payment system does not inherently require US dollars or SWIFT.\nStatement 2 — Correct\nDigital currencies can potentially have programmable conditions.\nConditions could relate to:\nWhere money can be spent.\nWhen it can be spent.\nPermitted uses.","revisionPoints":"CBDC → central-bank-issued digital money.\nCryptocurrency → generally decentralised/private digital asset.\nDigital payment ≠ CBDC.\nCBDC concepts:\nDigital sovereign currency\nProgrammability\nPayment infrastructure\nFinancial inclusion"},
{"no":73,"text":"In the context of finance, the term 'beta' refers to:","A":"The process of simultaneous buying and selling of an asset from different platforms","B":"An investment strategy to balance risk versus reward","C":"A type of systematic risk that arises where perfect hedging is not possible","D":"A numeric value that measures the fluctuations of a stock relative to the overall stock market","ans":"D","category":"Economy","subcategory":"Financial Markets","tags":["UPSC","2023"],"expl":"Beta measures the sensitivity of an asset's returns to movements in the broader market.\nBeta = 1 → moves roughly in line with the market.\nBeta &gt; 1 → greater sensitivity to market movements.\nBeta &lt; 1 → lower sensitivity.","revisionPoints":"Beta → market sensitivity\nAssociated with systematic risk.\nSystematic risk includes:\nRecession\nInterest-rate changes\nMajor geopolitical shocks\nStandard deviation → overall variability/volatility."},
{"no":74,"text":"Consider the following statements:\nThe Self-Help Group (SHG) programme was originally initiated by the State Bank of India.\nIn an SHG, all members take responsibility for loans taken by each member.\nRegional Rural Banks and Scheduled Commercial Banks support SHGs.\nHow many statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"B","category":"Economy","subcategory":"Banking","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nThe SHG-bank linkage model is strongly associated with NABARD, not originally initiated by SBI.\nStatement 2 — Correct\nSHGs operate through collective responsibility and mutual support.\nStatement 3 — Correct\nRegional Rural Banks and Scheduled Commercial Banks support SHGs through the banking linkage framework.","revisionPoints":"SHG → small voluntary group → savings → credit → collective responsibility.\nNABARD → SHG-Bank Linkage Programme\nSHGs are important for:\nFinancial inclusion\nRural credit\nWomen's empowerment\nCollective savings"},
{"no":75,"text":"Statement-I: India's public sector health care system largely focuses on curative care with limited preventive, promotive and rehabilitative care.\nStatement-II: Under India's decentralized approach to health care delivery, the States are primarily responsible for organizing health services.","A":"Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I.","B":"Both Statement-I and Statement-II are correct but Statement-II is not the correct explanation for Statement-I.","C":"Statement-I is correct but Statement-II is incorrect.","D":"Statement-I is incorrect but Statement-II is correct.","ans":"D","category":"Economy","subcategory":"Government Schemes","tags":["UPSC","2023"],"expl":"Statement-I — Incorrect\nIndia's public healthcare framework includes:\nPreventive care\nPromotive care\nCurative care\nRehabilitative care\nStatement-II — Correct\nHealth is primarily a State responsibility.\nThe Union Government also has important roles in policy, financing, national programmes and technical support.","revisionPoints":"Healthcare continuum:\nPreventive → Promotive → Curative → Rehabilitative\nPublic health and sanitation → State List.\nState subject does not mean the Union has no role."},
{"no":76,"text":"Statement-I: According to the United Nations World Water Development Report, 2022, India extracts more than a quarter of the world's groundwater withdrawal each year.\nStatement-II: India needs to extract more than a quarter of the world's groundwater each year to satisfy the drinking water and sanitation needs of almost 18% of the world's population living in its territory.","A":"Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I.","B":"Both Statement-I and Statement-II are correct but Statement-II is not the correct explanation for Statement-I.","C":"Statement-I is correct but Statement-II is incorrect.","D":"Statement-I is incorrect but Statement-II is correct.","ans":"C","category":"Environment & Ecology","subcategory":"Water Resources","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nIndia is one of the world's largest groundwater users.\nStatement-II — Incorrect\nGroundwater extraction is not simply due to drinking water and sanitation requirements.\nMajor factors include:\nIrrigation\nAgriculture\nDomestic use\nIndustrial use\nAgriculture is a particularly important driver.","revisionPoints":"India's groundwater challenge is linked with:\nIrrigation\nAgricultural electricity subsidies\nFalling water tables\nUrbanisation\nWater-intensive crops\nGroundwater dependence"},
{"no":77,"text":"Consider the following statements:\nAccording to the Constitution of India, the Central Government has a duty to protect States from internal disturbances.\nThe Constitution exempts States from providing legal counsel to persons held under preventive detention.\nAccording to the Prevention of Terrorism Act, 2002, confessions made before the police are admissible as evidence.\nHow many statements are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"B","category":"Polity & Governance","subcategory":"Fundamental Rights","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nArticle 355 places a duty on the Union to protect States against:\nExternal aggression\nInternal disturbance\nStatement 2 — Correct in the constitutional context\nPreventive detention has special constitutional provisions under Article 22.\nCertain safeguards applicable to ordinary arrests do not operate identically in preventive detention.\nStatement 3 — Incorrect as framed in the supplied material.","revisionPoints":"Article 355 → Union's duty to protect States.\nArticle 22 → protection against arrest and detention.\nPreventive detention → separately governed constitutional safeguards.\nDo not confuse:\nArticle 352 → National Emergency\nArticle 355 → Union's duty to protect States"},
{"no":78,"text":"Which one of the following countries has been suffering from decades of civil strife and food shortages and was in the news recently for its very severe famine?","A":"Angola","B":"Costa Rica","C":"Ecuador","D":"Somalia","ans":"D","category":"International Relations","subcategory":"Countries in News","tags":["UPSC","2023"],"expl":"Somalia has experienced prolonged:\nPolitical instability\nCivil conflict\nDrought\nFood insecurity\nHumanitarian crises\nIt is located in the Horn of Africa.","revisionPoints":"Horn of Africa includes:\nSomalia\nEthiopia\nEritrea\nDjibouti\nSomalia → easternmost part of the Horn of Africa.\nDrought and food insecurity are major regional concerns."},
{"no":79,"text":"Consider the following statements:\nIn India, the Biodiversity Management Committees are key to realizing the objectives of the Nagoya Protocol.\nBiodiversity Management Committees have important functions in determining access and benefit sharing, including the power to levy collection fees on access to biological resources within their jurisdiction.","A":"1 only","B":"2 only","C":"Both 1 and 2","D":"Neither 1 nor 2","ans":"C","category":"Environment & Ecology","subcategory":"Biodiversity","tags":["UPSC","2023"],"expl":"Both statements are correct.\nBiodiversity Management Committees (BMCs) operate at the local level.\nTheir functions relate to:\nBiodiversity documentation\nBiological resources\nTraditional knowledge\nAccess and Benefit Sharing\nNagoya Protocol focuses on:\nAccess to genetic resources\nFair and equitable sharing of benefits","revisionPoints":"Nagoya Protocol → Access and Benefit Sharing\nBMC → local biodiversity governance\nPeople's Biodiversity Register → important associated concept.\nConvention on Biological Diversity → broader biodiversity framework."},
{"no":80,"text":"Consider the following statements:\nNominated members of Parliament or State Legislatures are eligible to be included in the Electoral College.\nHigher the number of elected Assembly seats, higher is the value of vote of each MLA.\nThe value of vote of each MLA of Madhya Pradesh is greater than that of Kerala.\nThe value of vote of each MLA of Puducherry is higher than that of Arunachal Pradesh because the ratio of population to elected seats is higher.\nHow many of the above statements are correct?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"B","category":"Polity & Governance","subcategory":"President","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nNominated MPs/MLAs are not part of the Presidential Electoral College.\nStatement 2 — Incorrect\nVote value does not simply increase with the number of Assembly seats.\nIt depends on the prescribed population-to-elected-member ratio.\nStatement 3 — Correct\nThe value of an MLA's vote in Madhya Pradesh is higher than that of Kerala under the Presidential election formula.\nStatement 4 — Correct\nPuducherry's MLA vote value is higher than Arunachal Pradesh's under the relevant calculation.","revisionPoints":"Presidential Electoral College includes:\nElected MPs\nElected MLAs of States\nElected MLAs of Delhi\nElected MLAs of Puducherry\nDoes not include:\nNominated MPs\nNominated MLAs\nLegislative Council members\nMLA vote value broadly depends on:State population ÷ number of elected Assembly members\nMore MLAs ≠ automatically higher vote value."},
{"no":81,"text":"With reference to Indian History, Alexander Rea, A. H. Longhurst, Robert Sewell, James Burgess and Walter Elliot were associated with:","A":"Archaeological excavations","B":"Establishment of English Press in Colonial India","C":"Establishment of Churches in Princely States","D":"Construction of railways in Colonial India","ans":"A","category":"History","subcategory":"Ancient India","tags":["UPSC","2023"],"expl":"These individuals were associated with archaeological exploration, documentation and conservation in colonial India.\nImportant associations:\nJames Burgess → archaeological surveys and Indian architecture/inscriptions.\nRobert Sewell → South Indian history and Vijayanagara.\nAlexander Rea → archaeology in South India.\nA. H. Longhurst → archaeological conservation in South India.\nWalter Elliot → antiquarian studies and South Indian archaeology.","revisionPoints":"ASI → established in 1861.\nAlexander Cunningham → first Archaeological Surveyor/Director General.\nArchaeology includes:\nExcavation\nInscriptions\nMonuments\nCoins\nArchitecture\nMaterial remains"},
{"no":82,"text":"Consider the following pairs:\nSite\nWell known for\n1. Besnagar\nShaivite cave shrine\n2. Bhaja\nBuddhist cave shrine\n3. Sittanavasal\nJain cave shrine\nHow many of the above pairs are correctly matched?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"B","category":"History","subcategory":"Ancient India","tags":["UPSC","2023"],"expl":"Pair 1 — Incorrect\nBesnagar is famous particularly for the Heliodorus Pillar, associated with the Vaishnava/Bhagavata tradition.\nPair 2 — Correct\nBhaja Caves → Buddhist rock-cut caves.\nPair 3 — Correct\nSittanavasal → associated with Jainism.","revisionPoints":"Bhaja → Buddhist\nSittanavasal → Jain\nHeliodorus Pillar → Besnagar/Vidisha → Vaishnavism\nAjanta → predominantly Buddhist\nEllora → Buddhist + Hindu + Jain\nElephanta → predominantly Shaivite"},
{"no":83,"text":"Statement-I: 7th August is declared as the National Handloom Day.\nStatement-II: It was in 1905 that the Swadeshi Movement was launched on the same day.","A":"Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I.","B":"Both are correct but Statement-II is not the correct explanation.","C":"Statement-I is correct but Statement-II is incorrect.","D":"Statement-I is incorrect but Statement-II is correct.","ans":"A","category":"History","subcategory":"Modern India","tags":["UPSC","2023"],"expl":"Statement-I — Correct\n7 August is observed as National Handloom Day.\nStatement-II — Correct\nThe Swadeshi Movement was launched on 7 August 1905.\nThe date is associated with opposition to the partition of Bengal.\nThe movement promoted:\nIndigenous production\nSwadeshi goods\nBoycott of foreign goods\nTraditional industries","revisionPoints":"7 August → National Handloom Day\n7 August 1905 → Swadeshi Movement\nSwadeshi → indigenous production + boycott\nHandloom → traditional textile sector"},
{"no":84,"text":"Statement-I: One of the standard sizes of the National Flag of India is 600 mm × 400 mm.\nStatement-II: The ratio of the length to the height (width) of the Flag shall be 3 : 2.","A":"Both correct and II explains I","B":"Both correct but II does not explain I","C":"I correct, II incorrect","D":"I incorrect, II correct","ans":"D","category":"Polity & Governance","subcategory":"Constitution","tags":["UPSC","2023"],"expl":"Statement-I — Incorrect\n600 mm × 400 mm is not one of the prescribed standard sizes in the supplied material.\nStatement-II — Correct\nThe Indian National Flag has a 3:2 length-to-width ratio.","revisionPoints":"National Flag ratio → 3 : 2\nSaffron → top\nWhite → middle\nGreen → bottom\nAshoka Chakra → navy blue\nAshoka Chakra → 24 spokes"},
{"no":85,"text":"Statement-I: Constitution Day is celebrated on 26th November every year to promote constitutional values among citizens.\nStatement-II: On 26th November, 1949, the Constituent Assembly set up the Drafting Committee under Dr. B. R. Ambedkar.","A":"Both correct and II explains I","B":"Both correct but II does not explain I","C":"I correct, II incorrect","D":"I incorrect, II correct","ans":"C","category":"Polity & Governance","subcategory":"Constituent Assembly","tags":["UPSC","2023"],"expl":"Statement-I — Correct\n26 November is observed as Constitution Day.\nThe Constitution was adopted on 26 November 1949.\nStatement-II — Incorrect\nThe Drafting Committee was constituted on 29 August 1947.\nDr. B. R. Ambedkar was its Chairman.","revisionPoints":"Date\nEvent\n9 Dec 1946\nFirst meeting of Constituent Assembly\n29 Aug 1947\nDrafting Committee constituted\n26 Nov 1949\nConstitution adopted\n26 Jan 1950\nConstitution came into force"},
{"no":86,"text":"Statement-I: Switzerland is one of the leading exporters of gold in terms of value.\nStatement-II: Switzerland has the second largest gold reserves in the world.","A":"Both correct and II explains I","B":"Both correct but II does not explain I","C":"I correct, II incorrect","D":"I incorrect, II correct","ans":"C","category":"Economy","subcategory":"International Trade","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nSwitzerland is a major global centre for gold refining and trading.\nStatement-II — Incorrect\nSwitzerland does not possess the world's second-largest official gold reserves.\nA country can be a major exporter because of its refining and trading role, rather than its own reserves.","revisionPoints":"Switzerland is important for:\nGold refining\nBullion trade\nInternational financial services\nRemember:\nGold reserves ≠ gold refining/export activity"},
{"no":87,"text":"Statement-I: Recently, the USA and the European Union launched the Trade and Technology Council (TTC).\nStatement-II: The USA and the EU claim that through the TTC they are trying to bring technological progress and physical productivity under their control.","A":"Both correct and II explains I","B":"Both correct but II does not explain I","C":"I correct, II incorrect","D":"I incorrect, II correct","ans":"C","category":"International Relations","subcategory":"Organizations","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nThe US–EU Trade and Technology Council was established to strengthen cooperation.\nMajor areas include:\nTrade\nTechnology\nDigital governance\nSupply chains\nEmerging technologies\nStandards\nEconomic security\nStatement-II — Incorrect\nThe objective is not described as bringing technological progress and physical productivity “under their control.”","revisionPoints":"TTC → USA + EU\nFocus areas:\nTechnology\nTrade\nStandards\nDigital technologies\nSemiconductor supply chains\nCritical technologies\nEconomic security"},
{"no":88,"text":"Statement-I: India accounts for about 3.2% of global export of goods.\nStatement-II: Many local companies and some foreign companies operating in India have taken advantage of India's Production-Linked Incentive (PLI) scheme.","A":"Both correct and II explains I","B":"Both correct but II does not explain I","C":"I correct, II incorrect","D":"I incorrect, II correct","ans":"B","category":"Economy","subcategory":"Government Schemes","tags":["UPSC","2023"],"expl":"Statement-I — Correct in the context of the question.\nStatement-II — Correct\nCompanies have participated in the PLI framework.\nHowever, participation in PLI does not by itself explain India's overall share of global merchandise exports.\nTherefore, II does not explain I.","revisionPoints":"PLI aims to:\nIncrease domestic manufacturing\nAttract investment\nIncrease production\nPromote exports\nReduce import dependence\nIntegrate India into global supply chains"},
{"no":89,"text":"Consider the following statements:\nIt limits the levels of the budgetary deficit of EU countries.\nIt makes EU countries share their infrastructure facilities.\nIt enables EU countries to share their technologies.\nHow many are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"A","category":"International Relations","subcategory":"Organizations","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nThe Stability and Growth Pact is concerned with fiscal discipline.\nStatement 2 — Incorrect\nInfrastructure sharing is not its principal purpose.\nStatement 3 — Incorrect\nTechnology sharing is not its principal purpose.\nCommonly remembered fiscal reference values:\nBudget deficit → 3% of GDP\nPublic debt → 60% of GDP","revisionPoints":"SGP → Fiscal discipline\nFocus:\nBudget deficits\nPublic debt\nFiscal sustainability\nDo not confuse it with EU programmes dealing with:\nInfrastructure\nTechnology\nResearch\nRegional development"},
{"no":90,"text":"Consider the following statements:\nRecently, all the countries of the United Nations adopted the first-ever international migration pact, the Global Compact for Safe, Orderly and Regular Migration (GCM).\nThe objectives and commitments stated in the GCM are binding on UN member countries.\nThe GCM addresses internal migration or internally displaced persons.\nHow many are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"D","category":"International Relations","subcategory":"Organizations","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nThe GCM was adopted in 2018, but not all UN member states endorsed it.\nStatement 2 — Incorrect\nGCM is non-binding.\nStatement 3 — Incorrect\nIt deals with international migration, not internal migration or internally displaced persons.","revisionPoints":"GCM → Global Compact for Safe, Orderly and Regular Migration\nFocuses on:\nSafe migration\nOrderly migration\nRegular migration\nInternational cooperation\nProtection of migrants\nMigration drivers"},
{"no":91,"text":"With reference to Home Guards:\nHome Guards are raised under the Home Guards Act and Rules of the Central Government.\nThe role of Home Guards is to serve as an auxiliary force to the police in maintaining internal security.\nBorder Wing Home Guards Battalions have been raised in some States.\nHow many are correct?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"B","category":"Polity & Governance","subcategory":"Defence Administration","tags":["UPSC","2023"],"expl":"Statement 1 — Incorrect\nHome Guards are organised under the respective State/Union Territory framework.\nStatement 2 — Correct\nThey serve as an auxiliary force to assist the police.\nStatement 3 — Correct\nBorder Wing Home Guards Battalions have been raised in some States.","revisionPoints":"Home Guards can assist in:\nInternal security\nLaw and order\nCivil defence\nNatural disasters\nEmergencies\nBorder-related responsibilities\nRemember:\nPolice → primary forceHome Guards → auxiliary/support force"},
{"no":92,"text":"Consider the following pairs:\nAction\nAct\n1. Unauthorized wearing of police or military uniforms\nOfficial Secrets Act, 1923\n2. Knowingly misleading or interfering with a police/military officer on duty\nIndian Evidence Act, 1872\n3. Celebratory gunfire endangering others\nArms (Amendment) Act, 2019\nHow many are correctly matched?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"A","category":"Polity & Governance","subcategory":"Defence Administration","tags":["UPSC","2023"],"expl":"Pair 1 — Incorrect\nUnauthorized wearing of police/military uniforms is not correctly matched with the Official Secrets Act.\nPair 2 — Incorrect\nThe Indian Evidence Act deals primarily with rules of evidence.\nPair 3 — Correct\nThe Arms (Amendment) Act, 2019 introduced provisions concerning misuse of firearms, including dangerous celebratory firing.","revisionPoints":"Official Secrets Act → official information/secrets\nEvidence law → rules and admissibility of evidence\nArms Act → firearms and weapons regulation"},
{"no":93,"text":"Consider the following pairs:\nRegion\nReason for being in news\n1. North Kivu and Ituri\nWar between Armenia and Azerbaijan\n2. Nagorno-Karabakh\nInsurgency in Mozambique\n3. Kherson and Zaporizhzhia\nDispute between Israel and Lebanon\nHow many are correctly matched?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"D","category":"International Relations","subcategory":"Regional Conflicts","tags":["UPSC","2023"],"expl":"North Kivu and Ituri\nProvinces of the Democratic Republic of the Congo.\nAssociated with armed conflict and insurgency.\nNagorno-Karabakh\nAssociated with the Armenia–Azerbaijan conflict.\nKherson and Zaporizhzhia\nRegions of Ukraine, associated with the Russia–Ukraine conflict.","revisionPoints":"North Kivu/Ituri → DRC\nNagorno-Karabakh → Armenia–Azerbaijan\nKherson/Zaporizhzhia → Ukraine"},
{"no":94,"text":"Statement-I: Israel has established diplomatic relations with some Arab States.\nStatement-II: The Arab Peace Initiative mediated by Saudi Arabia was signed by Israel and Arab League.","A":"Both correct and II explains I","B":"Both correct but II does not explain I","C":"I correct, II incorrect","D":"I incorrect, II correct","ans":"C","category":"International Relations","subcategory":"Countries in News","tags":["UPSC","2023"],"expl":"Statement-I — Correct\nIsrael has diplomatic relations with several Arab states, including:\nEgypt\nJordan\nUAE\nBahrain\nMorocco\nStatement-II — Incorrect\nThe Arab Peace Initiative, proposed by Saudi Arabia in 2002, was a peace framework offered by Arab states.\nIt was not a treaty signed by Israel and the Arab League.","revisionPoints":"Arab Peace Initiative ≠ Abraham Accords\nPeace initiative ≠ peace treaty\nNormalisation agreement ≠ necessarily a peace treaty"},
{"no":95,"text":"Consider the following:\nMajor Dhyan Chand Khel Ratna Award – Most spectacular and outstanding performance over the previous four years.\nArjuna Award – Lifetime achievement by a sportsperson.\nDronacharya Award – To honour eminent coaches.\nRashtriya Khel Protsahan Puruskar – To recognize contribution made by sportspersons even after retirement.\nHow many are correctly matched?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"B","category":"Current Affairs","subcategory":"Awards & Honours","tags":["UPSC","2023"],"expl":"Pair 1 — Correct\nKhel Ratna recognises outstanding sporting performance.\nPair 2 — Incorrect\nArjuna Award recognises outstanding achievement in sports; it is not simply a lifetime achievement award.\nPair 3 — Correct\nDronacharya Award honours eminent coaches.\nPair 4 — Incorrect\nRashtriya Khel Protsahan Puruskar recognises contributions to the promotion and development of sports.","revisionPoints":"Khel Ratna → outstanding sporting performance\nArjuna → outstanding sportspersons\nDronacharya → coaches\nRashtriya Khel Protsahan Puruskar → promotion/development of sports"},
{"no":96,"text":"Consider the following:\nIt was the first time the Chess Olympiad was held in India.\nThe official mascot was named 'Thambi'.\nThe trophy for the Open section is the Vera Menchik Cup.\nThe trophy for the Women's section is the Hamilton-Russell Cup.\nHow many are correct?","A":"Only one","B":"Only two","C":"Only three","D":"All four","ans":"B","category":"Current Affairs","subcategory":"Sports","tags":["UPSC","2023"],"expl":"Statement 1 → Correct\nStatement 2 → Correct\nStatement 3 → Incorrect\nOpen section → Hamilton-Russell Cup\nVera Menchik Cup → Women's section\nStatement 4 → Incorrect\nTherefore, based on the statements themselves, two statements (1 and 2) are correct.","revisionPoints":"44th Chess Olympiad:\nYear → 2022\nVenue → Chennai\nFirst Chess Olympiad hosted by India\nMascot → Thambi\nOpen → Hamilton-Russell Cup\nWomen's → Vera Menchik Cup"},
{"no":97,"text":"Consider the following pairs:\nArea of conflict\nCountry\n1. Donbas\nSyria\n2. Kachin\nEthiopia\n3. Tigray\nNorth Yemen\nHow many are correctly matched?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"D","category":"International Relations","subcategory":"Regional Conflicts","tags":["UPSC","2023"],"expl":"Donbas → Ukraine, not Syria.\nKachin → Myanmar, not Ethiopia.\nTigray → Ethiopia, not North Yemen.\nTherefore, none of the pairs is correctly matched.","revisionPoints":"Donbas → Ukraine\nKachin → Myanmar\nTigray → Ethiopia\nFor conflict geography, remember:\nRegion → Country → Conflict"},
{"no":98,"text":"In recent years Chad, Guinea, Mali and Sudan caught international attention for which common reason?","A":"Discovery of rich deposits of rare earth elements","B":"Establishment of Chinese military bases","C":"Southward expansion of Sahara Desert","D":"Successful coups","ans":"D","category":"International Relations","subcategory":"Regional Conflicts","tags":["UPSC","2023"],"expl":"Chad, Guinea, Mali and Sudan experienced military coups or military takeovers during the relevant period.\nThese developments raised concerns about:\nDemocratic governance\nMilitary rule\nRegional instability\nTerrorism\nConstitutional order","revisionPoints":"Important coup-related countries in recent African current affairs:\nMali\nGuinea\nSudan\nChad\nBurkina Faso\nNiger\nMany of these developments were concentrated in or around the Sahel region."},
{"no":99,"text":"Consider the following:\nFertilizer plants\nOil refineries\nSteel plants\nGreen hydrogen is expected to play a significant role in decarbonizing how many of the above industries?","A":"Only one","B":"Only two","C":"All three","D":"None","ans":"C","category":"Science & Technology","subcategory":"Renewable Energy","tags":["UPSC","2023"],"expl":"Fertilizer plants — Correct\nHydrogen is required to produce ammonia.\nGreen hydrogen can replace fossil-fuel-derived hydrogen.\nOil refineries — Correct\nHydrogen is used in:\nHydrocracking\nDesulphurisation\nSteel plants — Correct\nHydrogen can be used in direct reduced iron (DRI) pathways as an alternative reducing agent.","revisionPoints":"Green hydrogen applications:\nFertilizers\nOil refining\nSteel\nHeavy transport\nEnergy storage\nChemicals\nGreen hydrogen → renewable electricity + electrolysis"},
{"no":100,"text":"Consider the following:\nThe G-20 group was originally established as a platform for Finance Ministers and Central Bank Governors to discuss international economic and financial issues.\nDigital Public Infrastructure (DPI) is one of India's G-20 priorities.\nHow many are correct?","A":"Only one","B":"Only two","C":"Both 1 and 2","D":"Neither 1 nor 2","ans":"C","category":"International Relations","subcategory":"Organizations","tags":["UPSC","2023"],"expl":"Statement 1 — Correct\nG20 was established in 1999.\nIt initially brought together:\nFinance Ministers\nCentral Bank Governors\nAfter the 2008 global financial crisis, it was elevated to the leaders' level.\nStatement 2 — Correct\nDigital Public Infrastructure was an important priority during India's G20 Presidency.\nIndia's DPI ecosystem includes:\nAadhaar\nUPI\nDigital identity\nDigital payments\nInteroperable digital platforms","revisionPoints":"G20 timeline\n1999 → Finance Ministers + Central Bank Governors\n2008 → Leaders' Summit became central\nIndia's Presidency → DPI, digital transformation, inclusive growth\nKey point:\nG20 was not originally a leaders-only forum."},
];
